// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: fund caller with 10 ether, send 1.5 ether to contract via Put
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        c.Put{value: 1.5 ether}(block.timestamp + 100); // unlockTime = now + 100

        // Warp past unlockTime
        vm.warp(block.timestamp + 200);

        // Now call Collect with _am = 2 ether, which is > balance (1.5 ether)
        // In reference: condition acc.balance >= _am fails, so call reverts.
        // In bug: condition removed, so call succeeds (sends 2 ether from contract balance, but fails on transfer because contract only has 1.5 ether? Actually call.value sends ether from *contract* balance, not from caller. Contract balance is 1.5 ether, so msg.sender.call{value: 2 ether} will fail due to insufficient balance. That causes _s = false, so balance not deducted. To avoid this, need contract to have enough ether. Let's instead fund contract with 5 ether via a separate call. Better: fund contract with enough ether so that send succeeds on buggy version but condition fails on reference.
        // We need contract.balance >= _am so that send works in buggy. But we also need acc.balance < _am so reference reverts. So let's set acc.balance = 1.5 ether, contract.balance = 5 ether (extra from another user). 
        // Simpler: just directly send ether to contract address via vm.deal.
        vm.deal(address(c), 5 ether);

        uint256 am = 2 ether;
        // Now call Collect
        vm.prank(caller);
        bool ok;
        try c.Collect(am) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference should revert (ok == false), buggy should not revert (ok == true)
        assertTrue(!ok, "Reference reverts, buggy may not");
    }
}

